SELECT soldDate, soldTargetName, soldTargetMobile, productName, productType, cardId, cardNum, soldAmount, soldOperatorId, soldOperatorName FROM ( SELECT DATE_FORMAT(bc.sold_date, '%Y-%m-%d') AS soldDate, bc.sold_target AS soldTargetName, bc.sold_phone_number AS soldTargetMobile, bcn.coupon_name AS productName, bcn.coupon_type AS productType, bc.card_id as cardId, bc.card_number AS cardNum, bcn.sold_amount AS soldAmount, bc.seller_user_id AS soldOperatorId, be.employee_name AS soldOperatorName FROM base_card bc LEFT JOIN base_coupon bcn ON bc.coupon_id = bcn.coupon_id LEFT JOIN base_employee be ON bc.seller_user_id = be.user_id
AND bc.sold_type = 0 -- 售卖 AND bc.charge_status = 1 -- 已收费 AND bc.`status` != 0 -- 非生成状态
AND bc.allocate_org_id = #{query.orgId}
AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bc.sold_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y') <= #{query.endDate}
ORDER BY bc.sold_date DESC ) bc
AND bc.soldTargetName LIKE concat('%', #{query.soldTargetName}, '%')
AND bc.soldTargetMobile LIKE concat('%', #{query.soldTargetMobile}, '%')
AND bc.cardNum LIKE concat('%', #{query.cardNum}, '%')
AND bc.productName LIKE concat('%', #{query.productName}, '%')
AND DATE_FORMAT(bc.soldDate, '%Y-%m-%d') >= #{query.soldStartDate}
AND DATE_FORMAT(bc.soldDate, '%Y-%m-%d') <= #{query.soldEndDate}

select `bp`.`name` as `patientName`, date_format(`bp`.first_visit_date, '%Y-%m-%d') as firstTreatDate, `bc`.`card_number`, date_format(`bc`.`active_date`, '%Y-%m-%d') as `activeDate`, (select `abbreviation` from `base_organization` where `org_id` = `bc`.`active_org_id`) as `activeOrgName`, (select `employee_name` from `base_employee` where `user_id` = `bc`.`active_user_id`) as `operateUser`, IF(`bc`.`status` in (3, 4), '是', '否') as `used` from `base_card` `bc` left join `base_coupon` `b` on `b`.`coupon_id` = `bc`.`coupon_id` inner join `base_patient` `bp` on `bp`.`patient_id` = `bc`.`patient_id` where `bc`.`coupon_id` = #{couponId} and `bc`.`sale_channel_id` = #{saleChannelId}
and bp.name like concat('%', #{patientKeyword}, '%')
and (DATE_FORMAT(`bc`.`active_date`,'%Y-%m-%d') between DATE_FORMAT(#{activeStartDate},'%Y-%m-%d') and DATE_FORMAT(#{activeEndDate},'%Y-%m-%d'))
and `bc`.`active_org_id` in
#{item}
order by `bc`.`active_date` desc

SELECT cd.active_date as activeDate,bo.abbreviation as orgName,bp.name as patientName, cd.sale_channel_name as saleChannelName,ci.coupon_name as couponName, case when ci.coupon_type = 0 then '代金券' when ci.coupon_type = 1 then '折扣券' when ci.coupon_type = 2 then '兑换券' when ci.coupon_type = 3 then '套餐券' when ci.coupon_type = 4 then '充值卡' else '' end as couponType, cd.card_number as cardNumber, case when cd.status in (0,1,2) then '否' else '是' end as status, be.employee_name as activeUserName FROM base_card cd LEFT JOIN base_employee be ON cd.active_user_id = be.user_id LEFT JOIN base_coupon ci on cd.coupon_id = ci.coupon_id LEFT JOIN base_organization bo on cd.active_org_id = bo.org_id LEFT JOIN base_patient bp on cd.patient_id = bp.patient_id
and cd.active_org_id in
#{item}
and cd.coupon_id in
#{couponId}
and cd.sale_channel_id in
#{saleChannelId}
and (DATE_FORMAT(cd.active_date,'%Y-%m-%d') between DATE_FORMAT(#{rechargeStartDate},'%Y-%m-%d') and DATE_FORMAT(#{rechargeEndDate},'%Y-%m-%d'))
order by cd.active_date desc

