SELECT
    t.orgId,
    bo.abbreviation,
    sum(t.soldNum) AS soldNum,
    sum(t.activedNum) AS activedNum
FROM (
    SELECT
        bb.org_id AS orgId,
        sum(bbd.quantity) soldNum,
        0 AS activedNum
    FROM base_bill_detail bbd
    LEFT JOIN base_bill bb ON bb.bill_id = bbd.bill_id

        and item_type = 1


                AND DATE_FORMAT(bb.bill_date, '%Y-%m-%d') >= #{query.startDate}


                AND DATE_FORMAT(bb.bill_date, '%Y-%m-%d') <= #{query.endDate}




                AND DATE_FORMAT(bb.bill_date, '%Y-%m') >= #{query.startDate}


                AND DATE_FORMAT(bb.bill_date, '%Y-%m') <= #{query.endDate}




                AND DATE_FORMAT(bb.bill_date, '%Y') >= #{query.startDate}


                AND DATE_FORMAT(bb.bill_date, '%Y') <= #{query.endDate}



            and bbd.item_id in

                #{itemId}



            and bb.org_id in

                #{orgId}



    GROUP BY bb.org_id
    UNION ALL
    /*卡券售出的售卖量*/
    SELECT
        bc.allocate_org_id AS orgId,
        count(bc.card_id) AS soldNum,
        0 AS activedNum
    FROM base_card bc

        AND bc.status in (1,2,3,4)


                AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') >= #{query.startDate}


                AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') <= #{query.endDate}




                AND DATE_FORMAT(bc.sold_date, '%Y-%m') >= #{query.startDate}


                AND DATE_FORMAT(bc.sold_date, '%Y-%m') <= #{query.endDate}




                AND DATE_FORMAT(bc.sold_date, '%Y') >= #{query.startDate}


                AND DATE_FORMAT(bc.sold_date, '%Y') <= #{query.endDate}



            and bc.coupon_id in

                #{couponId}



            and bc.allocate_org_id in

                #{orgId}



    GROUP BY bc.allocate_org_id
    UNION ALL
    SELECT
        bc.active_org_id AS orgId,
        0 AS soldNum,
        count(bc.card_id) AS activedNum
    FROM base_card bc

        AND bc.status in (2,3,4)


                AND DATE_FORMAT(bc.active_date, '%Y-%m-%d') >= #{query.startDate}


                AND DATE_FORMAT(bc.active_date, '%Y-%m-%d') <= #{query.endDate}




                AND DATE_FORMAT(bc.active_date, '%Y-%m') >= #{query.startDate}


                AND DATE_FORMAT(bc.active_date, '%Y-%m') <= #{query.endDate}




                AND DATE_FORMAT(bc.active_date, '%Y') >= #{query.startDate}


                AND DATE_FORMAT(bc.active_date, '%Y') <= #{query.endDate}



            and bc.coupon_id in

                #{couponId}



            and bc.active_org_id in

                #{orgId}



    GROUP BY bc.active_org_id
) t
INNER JOIN base_organization bo ON bo.org_id = t.orgId
WHERE bo.org_type = 2
GROUP BY t.orgId
ORDER BY t.orgId

SELECT t.cardId, t.couponId, t.saleType, IF(t.saleType=1, '门诊开单', '卡券售出') AS soldType, t.couponName, t.soldDate, CONCAT(IFNULL(t.soldTarget, bp.name), IFNULL(t.mobile, bp.mobile)) AS patientIdentifies, IFNULL(t.soldTarget, bp.name) AS soldTarget, IFNULL(t.mobile, bp.mobile) AS mobile, bo.abbreviation, CASE WHEN bp.treatCount is NULL THEN '--' WHEN bp.treatCount = 1 THEN '初诊' ELSE '复诊' END AS firstVisit FROM ( SELECT bb.org_id AS orgId, bb.patient_id AS patientId, bbd.bill_detail_id AS cardId, bbd.item_id AS couponId, 1 AS saleType, bti.item_name AS couponName, NULL AS soldTarget, NULL AS mobile, DATE_FORMAT(bb.bill_date, '%Y-%m-%d %H:%i') AS soldDate FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bb.bill_id = bbd.bill_id LEFT JOIN base_tariff_info bti ON bti.item_id=bbd.item_id AND bti.item_type=bbd.item_type
and bbd.item_type = 1
AND DATE_FORMAT(bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bb.bill_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bb.bill_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bb.bill_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bb.bill_date, '%Y') <= #{query.endDate}
and bbd.item_id in
#{itemId}
and bb.org_id = #{query.orgId}
UNION ALL SELECT bc.allocate_org_id AS orgId, IFNULL(bc.patient_id, 0) AS patientId, bc.card_id AS cardId, bc.coupon_id AS couponId, 2 AS saleType, bcp.coupon_name AS couponName, IF(bc.patient_id IS NULL, sold_target, NULL) AS soldTarget, IF(bc.patient_id IS NULL, sold_phone_number, NULL) AS mobile, DATE_FORMAT(IFNULL(bc.sold_date, bc.active_date), '%Y-%m-%d %H:%i') AS soldDate FROM base_card bc LEFT JOIN base_coupon bcp ON bcp.coupon_id = bc.coupon_id
AND bc.status in (1,2,3,4) AND bc.card_password IS NOT NULL
AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bc.sold_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bc.sold_date, '%Y') <= #{query.endDate}
and bc.coupon_id in
#{couponId}
and bc.allocate_org_id = #{query.orgId}
) t LEFT JOIN ( SELECT bp.patient_id,bp.`name`,bp.mobile,btp.treatCount FROM base_patient bp LEFT JOIN ( SELECT COUNT(patient_id) AS treatCount, patient_id FROM base_treatment_process WHERE treat_end_time is not null GROUP BY patient_id ) btp ON bp.patient_id = btp.patient_id ) bp ON t.patientId = bp.patient_id INNER JOIN base_organization bo ON bo.org_id = t.orgId
AND bo.org_type = 2
AND t.saleType = #{query.soldType}
AND bp.treatCount = 1
AND bp.treatCount > 1
ORDER BY t.soldDate DESC, t.patientId, t.couponId

SELECT bc.card_id AS cardId, bc.coupon_id AS couponId, CONCAT(bp.name, bp.mobile) AS patientIdentifies, bc.sale_channel_name AS saleChannelName, bo.abbreviation, bcp.coupon_name AS couponName, bp.name AS patientName, bp.mobile, DATE_FORMAT(bc.active_date, '%Y-%m-%d %H:%i') AS activeDate, DATE_FORMAT(bc.activation_deadline, '%Y-%m-%d %H:%i') AS activationDeadline, CASE WHEN bp.treatCount is NULL THEN '--' WHEN bp.treatCount = 1 THEN '初诊' ELSE '复诊' END AS firstVisit FROM base_card bc INNER JOIN base_organization bo ON bo.org_id = bc.active_org_id INNER JOIN ( SELECT bp.patient_id, bp.`name`, bp.mobile, btp.treatCount FROM base_patient bp LEFT JOIN ( SELECT COUNT(patient_id) AS treatCount, patient_id FROM base_treatment_process WHERE treat_end_time is not null GROUP BY patient_id ) btp ON bp.patient_id = btp.patient_id ) bp ON bc.patient_id = bp.patient_id LEFT JOIN base_coupon bcp ON bcp.coupon_id = bc.coupon_id
AND bo.org_type = 2 AND bc.status in (2,3,4)
AND bp.treatCount = 1
AND bp.treatCount > 1
AND DATE_FORMAT(bc.active_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(bc.active_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT(bc.active_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bc.active_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT(bc.active_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT(bc.active_date, '%Y') <= #{query.endDate}
and bc.coupon_id in
#{couponId}
and bc.sale_channel_id in
#{saleChannelId}
and bc.active_org_id = #{query.orgId}
ORDER BY bc.active_date DESC, bp.patient_id, bc.coupon_id

select cb.bill_date as soldDate,
       cb.bill_num  AS billNumber,
       bp.name      as soldTargetName,
       bp.mobile    as soldTargetMobile,
       be.employee_name AS soldOperatorName,
       sum(case
               when cbpd.account_item_name = '会员卡' then cbpd.principal_amount
               else 0 end) memberPrincipalAmount,
       sum(case
               when cbpd.account_item_name = '会员卡' then cbpd.bonus_amount
               else 0 end) memberBonusAmount,
       sum(case
               when cbpd.account_item_name = '预付款' then cbpd.principal_amount
               else 0 end) prepayPrincipalAmount,
       sum(case
               when cbpd.account_item_name = '预付款' then cbpd.bonus_amount
               else 0 end) prepayBonusAmount,
       sum(case
               when cbpd.account_item_name = '支付宝' then cbpd.amount
               else 0 end) aliPayAmount,
       sum(case
               when cbpd.account_item_name = '微信' then cbpd.amount
               else 0 end) weChatAmount,
       sum(case
               when cbpd.account_item_name = '银行账户' then cbpd.amount
               else 0 end) bankAmount,
       sum(case
               when cbpd.account_item_name = '现金' then cbpd.amount
               else 0 end) cashAmount,
       sum(case
               when cbpd.account_item_name = '杭州医保' then cbpd.amount
               else 0 end) hzInsurance
from base_coupon_bill cb
         left join base_patient bp on bp.patient_id = cb.patient_id
         left join base_coupon_bill_pay_detail cbpd on cb.order_id = cbpd.order_id
         LEFT JOIN base_employee be ON cb.checker_id = be.user_id

    AND cb.`order_status` != 0

        AND cb.org_id = #{query.orgId}



            AND DATE_FORMAT(cb.bill_date, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT(cb.bill_date, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT(cb.bill_date, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT(cb.bill_date, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT(cb.bill_date, '%Y') >= #{query.startDate}


            AND DATE_FORMAT(cb.bill_date, '%Y') <= #{query.endDate}



            AND concat(IFNULL(bp.name, ''), IFNULL(bp.pinyin_name, ''), IFNULL(bp.mobile, '')) like
            concat('%', #{query.patientKey}, '%')


            AND DATE_FORMAT(cb.bill_date, '%Y-%m-%d') >= #{query.billStartDate}


            AND DATE_FORMAT(cb.bill_date, '%Y-%m-%d') <= #{query.billEndDate}


group by cb.order_id
ORDER BY cb.bill_date DESC

select cb.refund_date as refundDate,
       cb.bill_num  AS billNumber,
       bp.name      as refundTargetName,
       bp.mobile    as refundTargetMobile,
       be.employee_name AS refundOperatorName,
       sum(case
               when cbpd.account_item_name = '会员卡' then cbpd.principal_amount
               else 0 end) memberPrincipalAmount,
       sum(case
               when cbpd.account_item_name = '会员卡' then cbpd.bonus_amount
               else 0 end) memberBonusAmount,
       sum(case
               when cbpd.account_item_name = '预付款' then cbpd.principal_amount
               else 0 end) prepayPrincipalAmount,
       sum(case
               when cbpd.account_item_name = '预付款' then cbpd.bonus_amount
               else 0 end) prepayBonusAmount,
       sum(case
               when cbpd.account_item_name = '支付宝' then cbpd.total_amount
               else 0 end) aliPayAmount,
       sum(case
               when cbpd.account_item_name = '微信' then cbpd.total_amount
               else 0 end) weChatAmount,
       sum(case
               when cbpd.account_item_name = '银行账户' then cbpd.total_amount
               else 0 end) bankAmount,
       sum(case
               when cbpd.account_item_name = '现金' then cbpd.total_amount
               else 0 end) cashAmount,
       sum(case
               when cbpd.account_item_name = '杭州医保' then cbpd.total_amount
               else 0 end) hzInsurance
from base_coupon_refund cb
         left join base_patient bp on bp.patient_id = cb.patient_id
         left join base_coupon_refund_pay cbpd on cb.refund_id = cbpd.refund_id
         LEFT JOIN base_employee be ON cb.refund_operator_id = be.user_id


        AND cb.org_id = #{query.orgId}



            AND DATE_FORMAT(cb.refund_date, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT(cb.refund_date, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT(cb.refund_date, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT(cb.refund_date, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT(cb.refund_date, '%Y') >= #{query.startDate}


            AND DATE_FORMAT(cb.refund_date, '%Y') <= #{query.endDate}



            AND concat(IFNULL(bp.name, ''), IFNULL(bp.pinyin_name, ''), IFNULL(bp.mobile, '')) like
            concat('%', #{query.patientKey}, '%')


           AND DATE_FORMAT(cb.refund_date, '%Y-%m-%d') >= #{query.refundStartDate}


            AND DATE_FORMAT(cb.refund_date, '%Y-%m-%d') <= #{query.refundEndDate}


group by cb.refund_id
ORDER BY cb.refund_date DESC
